   "id": "zbc3d0e66",
   "sez": "viaggi",
   "titolo": "Campania, la rinascita di Roscigno nel Cilento da borgo fantasma a meta turistica",
   "orig": "Fino al 2024 aveva un unico abitante: oggi questo borgo del Cilento è diventato una (bellissima) ghost town",
   "lead": "Il comune di Roscigno, situato nel cuore montano del Cilento, si è trasformato da borgo pressoché spopolato in una suggestiva città fantasma capace di attirare visitatori e viaggiatori interessati al turismo delle origini. Il paese campano, che fino al 2024 contava un solo abitante residente stabile, rappresenta un esempio di resilienza territoriale e di valorizzazione del patrimonio architettonico storico. La riscoperta dei borghi abbandonati dell'Appennino meridionale offre un'esperienza di viaggio lenta, incentrata sulle radici culturali e sul recupero della memoria delle comunità rurali del passato. Lo riferisce Turisti per Caso.",
   "more": [
    "Il fenomeno dei borghi abbandonati in Italia è legato storicamente alle frane, all'emigrazione e allo spopolamento verso le grandi città industriali nel secondo dopoguerra. Negli ultimi anni il turismo culturale e naturalistico ha favorito iniziative di recupero per trasformare questi centri silenziosi in parchi archeologici all'aperto o musei diffusi."
   ],
