   "id": "z90eade8e",
   "sez": "cultura",
   "titolo": "Inaugurata a Praga l'edizione del festival radiofonico Prix Bohemia con la consegna dei premi",
   "orig": "Prizes presented at opening of Prix Bohemia radio festival",
   "lead": "La cerimonia inaugurale del festival radiofonico Prix Bohemia ha aperto ufficialmente i lavori a Praga con la consegna dei primi riconoscimenti ai professionisti del settore dell'emittenza vocale. La manifestazione, dedicata alle produzioni audio e alle innovazioni del giornalismo radiofonico, ha premiato programmi e autori distintisi per qualità editoriale e creatività narrativa. L'evento rappresenta una storica vetrina per il confronto tra operatori dei media pubblici e privati, riuniti per analizzare l'evoluzione dei formati documentari, delle fiction sonore e della trasmissione di contenuti informativi. Lo riferisce Radio Prague International.",
   "more": [
    "Il Prix Bohemia Radio è una delle rassegne più longeve dedicate all'arte radiofonica in Europa centrale. Il concorso esamina ogni anno opere suddivise in diverse sezioni, come documentari, drammi sonori e reportage, promuovendo standard professionali di qualità e lo scambio culturale tra emittenti europee."
   ],
