   "id": "zb29770b1",
   "sez": "ambiente",
   "titolo": "Tallahassee, una statua di gallio del governatore DeSantis si scioglie per protesta climatica",
   "orig": "Melting Ron DeSantis statue unveiled to call out his inaction on climate crisis",
   "lead": "Una statua a grandezza naturale raffigurante il governatore della Florida Ron DeSantis è stata svelata a Tallahassee ed è stata fatta sciogliere davanti al pubblico per denunciare l'assenza di provvedimenti statali contro la crisi climatica. La scultura, fusa in gallio metallico a basso punto di fusione, è collassata progressivamente fino a rivelare un teschio sotto i lineamenti del politico. L'azione dimostrativa ha preso di mira l'opposizione sistematica del governatore alle normative per tagliare i gas serra, da lui definite un'agenda climatica radicale in contrasto con le esigenze economiche locali.",
   "more": [
    "Il gallio è un metallo post-transizione che fonde a circa 29,7 gradi Celsius, caratteristica che consente di farlo passare dallo stato solido a quello liquido a temperatura ambiente o con modeste fonti di calore. Questa proprietà chimica è stata impiegata come metafora visiva per rappresentare l'innalzamento delle temperature globali."
   ],
