   "id": "z8f616bf6",
   "sez": "cultura",
   "titolo": "Premi del Consiglio Nordico: la Norvegia vince per la prima volta in tutte le categorie",
   "orig": "De vinner Nordiska rådets pris – norsk totaldominans",
   "lead": "L'edizione annuale dei prestigiosi premi culturali assegnati dal Consiglio Nordico si è conclusa con una vittoria totale degli autori norvegesi, che si sono imposti in tutte e cinque le sezioni in concorso. Il Paese ha conquistato i riconoscimenti per letteratura, narrativa per l'infanzia, musica, tutela dell'ambiente e cinema, dove ha trionfato il film 'Sentimental value' interpretato da Stellan Skarsgård e Renate Reinsve. Si tratta di un risultato senza precedenti storici per la manifestazione interparlamentare, che non aveva mai visto prima d'ora un singolo Stato conquistare l'intero palmarès dei premi scandinavi.",
   "more": [
    "Il Consiglio Nordico, istituito per promuovere la cooperazione tra Danimarca, Finlandia, Islanda, Norvegia e Svezia, conferisce ogni anno questi premi per celebrare l'eccellenza artistica e l'impegno ecologico nella regione. Il riconoscimento cinematografico e letterario rappresenta uno dei più autorevoli trampolini internazionali per la produzione culturale del Nord Europa."
   ],
