   "id": "ze3df32e0",
   "sez": "musica",
   "titolo": "Psyché pubblica il secondo album tra suggestioni mediterranee e ricerca sonora",
   "orig": "Psyché - Psyché II",
   "lead": "Il progetto musicale Psyché ha pubblicato il disco intitolato Psyché II, secondo capitolo discografico della propria carriera artistica. L'opera esplora le molteplici radici sonore del bacino del Mediterraneo, fondendo ritmiche tradizionali e contaminazioni globali in un viaggio espressivo che si spinge oltre i confini geografici convenzionali. Il lavoro sviluppa un linguaggio musicale ipnotico e strumentale, in cui le melodie modali e l'intreccio di percussioni dialogano con influenze contemporanee, delineando una precisa identità compositiva all'interno della scena world music e psichedelica indipendente. Lo riferisce OndaRock.",
   "more": [
    "L'area mediterranea è storicamente un crocevia di linguaggi musicali che uniscono scale del Medio Oriente, tradizioni greche e canti dell'Italia meridionale. La riscoperta moderna di questi suoni avviene spesso tramite l'ibridazione con il rock psichedelico, l'elettronica e l'improvvisazione etnica."
   ],
