   "id": "zc01dc46a",
   "sez": "tech",
   "titolo": "Il Regno Unito punta ad allentare il controllo di Apple sui pagamenti senza contatto",
   "orig": "Britain seeks to break Apple's grip on contactless payments",
   "lead": "Il Regno Unito intende adottare misure regolatorie per spezzare il predominio esercitato da Apple sui pagamenti senza contatto all'interno del proprio ecosistema tecnologico. Le autorità britanniche guardano con attenzione alla gestione del chip per le transazioni di prossimità integrato negli iPhone, con l'obiettivo di favorire una maggiore concorrenza e consentire a sviluppatori terzi e servizi bancari alternativi di accedere alle funzionalità hardware senza le attuali restrizioni. L'iniziativa rientra nelle politiche di controllo antitrust mirate a limitare le posizioni dominanti dei colossi tecnologici sui mercati digitali. Lo riferisce CNA.",
   "more": [
    "I sistemi di pagamento contactless tramite smartphone si basano sulla tecnologia NFC (Near Field Communication). Per anni Apple ha limitato l'accesso diretto a tale componente hardware sui propri dispositivi, riservandolo in via esclusiva ad Apple Pay per motivi dichiarati di sicurezza e privacy, scelta contestata da banche e autorità della concorrenza."
   ],
