   "sez": "cucina",
   "titolo": "Risotto ai funghi: i 5 errori da non fare per un risultato perfetto",
   "orig": "Risotto ai funghi: 5 errori da evitare per farlo perfetto",
   "lead": "La Cucina Italiana ha stilato una guida dedicata agli errori più frequenti da evitare nella preparazione del risotto ai funghi, per ottenere una pietanza cremosa ed equilibrata. Il servizio analizza nel dettaglio tutti i passaggi chiave della ricetta, partendo dai criteri per selezionare la tipologia di riso più idonea alla tenuta di cottura fino alla scelta delle varietà di funghi più adatte per esaltare i sapori del bosco. Vengono inoltre fornite indicazioni tecniche sulla tostatura, la gestione del brodo e la fase finale della mantecatura. Lo riferisce La Cucina Italiana.",
   "more": [
    "Per la riuscita di un risotto classico è fondamentale l'uso di riso ad alto contenuto di amilosio, come Carnaroli o Vialone Nano, capace di assorbire i liquidi mantenendo i chicchi integri. I funghi richiedono attenzioni nella pulizia e tempi di cottura calibrati per evitare che rilascino eccessiva acqua rovinando la consistenza."
   ],
