   "id": "z89f19bcc",
   "sez": "adolescenti",
   "titolo": "Proprietà e utilizzi degli idrogel: come assorbono l'acqua",
   "orig": "Let’s learn about hydrogels",
   "lead": "Un articolo divulgativo approfondisce le caratteristiche e il funzionamento degli idrogel, materiali a base polimerica capaci di trattenere straordinarie quantità di acqua al proprio interno. Grazie alla loro speciale struttura reticolare, queste sostanze possono espandersi senza sciogliersi, rendendosi estremamente preziose per una vasta serie di impieghi pratici. La trattazione spiega in modo accessibile come gli idrogel vengano utilizzati in diversi campi della vita quotidiana e dell'industria, dai dispositivi per la cura personale fino ai settori più avanzati della tecnologia e dell'agricoltura sostenibile. Lo riferisce Science News Explores.",
   "more": [
    "Gli idrogel sono polimeri idrofili tridimensionali in grado di assorbire fluidi fino a centinaia di volte il proprio peso secco. Trovano largo impiego biomedico nelle medicazioni per ferite e nella somministrazione controllata di farmaci, oltre che nella produzione di lenti a contatto e pannolini assorbenti."
   ],
