   "titolo": "Indonesia, frammento spaziale precipita in una piantagione di palme",
   "orig": "Near miss: Indonesia probes crash of suspected Chinese rocket fragment",
   "lead": "Le autorità indonesiane hanno avviato un'indagine dopo che un grande rottame metallico, delle dimensioni di un'automobile, si è schiantato martedì all'interno di una piantagione di palme da olio, a poca distanza da abitazioni e cantieri di lavoro. Secondo un'agenzia governativa locale, il pezzo di detrito spaziale potrebbe essere un frammento appartenente a un razzo cinese rientrato in modo incontrollato nell'atmosfera terrestre. La caduta non ha provocato vittime o feriti, ma ha sollevato allarme tra la popolazione residente nell'area per i rischi legati ai residui orbitali. Lo riferisce Phys.org – Spazio.",
   "more": [
    "Il rientro incontrollato di stadi di vettori spaziali costituisce una problematica ricorrente nella gestione dei detriti in orbita terrestre. Sebbene la maggior parte dei frammenti si disintegri per attrito a contatto con gli strati densi dell'atmosfera o ricada negli oceani, i componenti metallici più resistenti possono raggiungere la superficie terrestre."
   ],
