   "sez": "viaggi",
   "titolo": "I consigli e le regole per viaggiare a Hong Kong: i periodi da evitare",
   "orig": "The Unwritten Rules of Traveling to Hong Kong—Including the Time of Year You Should Absolutely Avoid",
   "lead": "Condé Nast Traveler ha pubblicato una guida pratica dedicata a chi pianifica un viaggio a Hong Kong, metropoli frequentemente inserita in itinerari internazionali più ampi. L'articolo riassume le convenzioni sociali e le regole non scritte fondamentali per muoversi in città in maniera consapevole, illustrando le migliori strategie per organizzare la visita senza contrattempi. Tra i suggerimenti principali spiccano le indicazioni sul clima, con la segnalazione del periodo dell'anno da evitare assolutamente a causa di condizioni meteorologiche sfavorevoli o di picchi di umidità e tifoni che condizionano gli spostamenti. Lo riferisce Condé Nast Traveler.",
   "more": [
    "Hong Kong presenta un clima subtropicale caratterizzato da inverni miti e asciutti ed estati calde e torrenziali. Tra la tarda primavera e l'inizio dell'autunno la regione è soggetta a frequenti precipitazioni monsoniche e all'allerta per il passaggio di tifoni tropicali, fattori che possono bloccare i trasporti urbani e aerei."
   ],
