   "id": "zbc556cc5",
   "sez": "cultura",
   "titolo": "Gengis Khan e l'eredità mongola al centro di una mostra a Berlino",
   "orig": "Brutal, revolutionary empire builder: Genghis Khan's legacy",
   "lead": "La città di Berlino ospita un'importante esposizione museale incentrata sulla figura di Gengis Khan e sui sovrani che ne proseguirono la dinastia imperiale. La mostra esplora il profilo del condottiero come fondatore brutale ma allo stesso tempo rivoluzionario dell'Impero Mongolo, evidenziando il modo in cui le sue conquiste abbiano sconvolto e trasformato il corso della storia eurasiatica. Il percorso espositivo mette a confronto la devastazione bellica delle sue invasioni con l'apertura delle rotte commerciali continentali e la conseguente integrazione culturale e amministrativa che caratterizzò quell'epoca. Lo riferisce Deutsche Welle.",
   "more": [
    "All'inizio del XIII secolo Gengis Khan unificò le tribù nomadi mongole creando uno degli imperi contigui più vasti della storia umana. Sotto la cosiddetta «Pax Mongolica», le vie di comunicazione tra Asia ed Europa furono riorganizzate, garantendo scambi commerciali lungo la Via della Seta e una temporanea tolleranza religiosa e amministrativa."
   ],
