   "titolo": "Tagikistan, un film sui poeti Jami e Navoi vince il premio Toji Somon",
   "orig": "Film about Jami and Navoi wins Grand Prix at Tajikistan’s Toji Somon awards",
   "lead": "Un'opera cinematografica incentrata sulle storiche figure dei poeti Jami e Navoi ha conquistato il prestigioso Gran Premio nell'ambito del festival cinematografico Toji Somon, tenutosi in Tagikistan. La premiazione ha visto l'assegnazione di diversi riconoscimenti ad artisti e registi che si sono distinti durante l'evento culturale centroasiatico. La pellicola vincitrice rende omaggio alla profonda amicizia intellettuale e al dialogo letterario tra i due illustri maestri della poesia classica persiana e chagatai, celebrando un patrimonio culturale condiviso tra i popoli della regione. Lo riferisce Asia-Plus.",
   "more": [
    "Noureddin Jami e Alisher Navoi furono due figure fondamentali del Rinascimento timuride nel XV secolo. La loro collaborazione simboleggia l'interazione armoniosa tra la lingua e letteratura persiana e quella turca chagatai, rimanendo un pilastro dell'identità letteraria in molti Paesi dell'Asia centrale."
   ],
