   "id": "z0318cd24",
   "sez": "salute",
   "titolo": "Ciad orientale: operati di cataratta i rifugiati fuggiti dal Sudan",
   "orig": "Free eye surgery camp targets Sudanese refugees in eastern Chad",
   "lead": "Nel comune di Adré, situato nella parte orientale del Ciad, è stato allestito un campo medico umanitario per eseguire interventi chirurgici oculistici gratuiti a beneficio dei rifugiati sudanesi. L'iniziativa sanitaria si concentra principalmente sulla rimozione della cataratta, offrendo assistenza medica specializzata alle centinaia di persone fuggite dalle violenze del conflitto in Sudan che soffrono di problemi alla vista e non dispongono di alcun accesso alle cure. Le operazioni consentono di prevenire forme di cecità curabile all'interno dei campi di accoglienza allestiti oltreconfine. Lo riferisce Radio Tamazuj.",
   "more": [
    "La guerra civile in Sudan, scoppiata nell'aprile 2023, ha provocato una delle peggiori crisi umanitarie del pianeta, spingendo centinaia di migliaia di persone a cercare rifugio oltre il confine con il Ciad. Nelle zone di frontiera le strutture sanitarie locali faticano a gestire l'enorme afflusso di sfollati con patologie croniche o pregresse."
   ],
