   "id": "zb2813d5d",
   "sez": "adolescenti",
   "titolo": "Pavia, quattordicenne cambia istituto ma continua a essere bullizzato: 7 denunce",
   "orig": "Cambia scuola, ma gli ex compagni continuano a bullizzarlo: 7 minorenni denunciati",
   "lead": "A Pavia un ragazzo di 14 anni ha continuato a essere preso di mira e perseguitato da un gruppo di ex compagni di scuola da cui aveva tentato di allontanarsi cambiando istituto scolastico. Il trasferimento in un nuovo plesso non è bastato a restituirgli la necessaria serenità, a causa delle continue pressioni e vessazioni perpetrate dalla comitiva di coetanei anche all'esterno dell'ambiente formativo originario. La vicenda si è conclusa con l'intervento delle forze dell'ordine e la conseguente denuncia a piede libero per sette minorenni ritenuti responsabili delle azioni intimidatorie. Lo riferisce Orizzonte Scuola.",
   "more": [
    "Il bullismo tra adolescenti può assumere forme continuative che travalicano i confini fisici della scuola, estendendosi ai luoghi di aggregazione e ai canali telematici. L'ordinamento italiano prevede specifici protocolli di prevenzione e sensibilizzazione negli istituti, affiancati dall'intervento della giustizia minorile nei casi in cui le condotte integrino reati perseguibili."
   ],
