   "sez": "italia",
   "titolo": "Pensionamento del personale scolastico nel 2027: domande di cessazione entro il 21 ottobre",
   "orig": "Pensioni scuola 2027, domande di cessazione entro il 21 ottobre",
   "lead": "Il personale del comparto scuola intenzionato ad accedere al pensionamento con decorrenza dal 1° settembre 2027 ha tempo fino al 21 ottobre 2026 per inoltrare la richiesta formale di cessazione dal servizio. La data rappresenta il termine perentorio fissato per la presentazione delle istanze da parte di docenti e operatori amministrativi, tecnici e ausiliari degli istituti statali. L'adempimento procedurale consente all'amministrazione di censire le uscite previste e di pianificare la gestione degli organici e delle immissioni in ruolo per l'anno scolastico successivo. Lo riferisce Orizzonte Scuola.",
   "more": [
    "Nel sistema scolastico italiano le domande di pensionamento devono essere presentate con quasi un anno di anticipo rispetto all'avvio dell'anno scolastico di riferimento. Questa tempistica consente al Ministero dell'Istruzione di quantificare i posti vacanti in vista dei trasferimenti del personale di ruolo e delle future graduatorie di assunzione."
   ],
