   "id": "z2aa64cee",
   "sez": "musica",
   "titolo": "Harry Styles pubblica un nuovo brano in cui ricorda l'ex compagno di band Liam Payne",
   "orig": "Harry Styles ha trovato le parole giuste per ricordare Liam Payne",
   "lead": "Il cantante Harry Styles ha affrontato pubblicamente il lutto per la scomparsa di Liam Payne attraverso la pubblicazione di un nuovo brano musicale. L'artista britannico offre nella canzone una testimonianza personale volta a elaborare la perdita dell'amico ed ex compagno negli One Direction, condividendo con gli ascoltatori una riflessione intimista sulla difficoltà di comprendere la morte prematura del collega. L'omaggio segna un momento di raccoglimento artistico seguito alla scomparsa di Payne, figura centrale nel percorso di esordio musicale e nel successo internazionale condiviso dai due cantanti. Lo riferisce Rolling Stone Italia.",
   "more": [
    "Harry Styles e Liam Payne hanno condiviso il debutto globale negli One Direction, boy band formata nel 2010 durante l'edizione britannica del programma X Factor. Dopo anni di successi discografici e tournée mondiali con milioni di dischi venduti, i componenti del gruppo avevano intrapreso carriere da solisti."
   ],
