   "id": "ze1721359",
   "sez": "viaggi",
   "titolo": "Agoda raddoppia l'offerta di hotel di lusso mentre aumentano le ricerche per le cinque stelle",
   "orig": "Agoda Doubles Premium Hotel Supply as Five-Star Search Rises",
   "lead": "La piattaforma online di prenotazioni turistiche Agoda ha raddoppiato la disponibilità di strutture alberghiere di fascia alta, assecondando la crescita delle ricerche da parte degli utenti interessati a hotel a cinque stelle. L'espansione del portafoglio di lusso rappresenta un tentativo di posizionamento sul mercato dell'ospitalità d'élite. Gli analisti del comparto turistico evidenziano tuttavia che, fino a quando la compagnia non mostrerà dati consolidati sulle prenotazioni effettivamente concluse, non vi saranno prove certe sulla reale capacità della piattaforma di competere stabilmente nella vendita di soggiorni nel segmento del turismo premium. Lo riferisce Skift.",
   "more": [
    "Le agenzie di viaggio online (OTA) puntano con frequenza a differenziare la clientela ampliando i servizi per la fascia di lusso, caratterizzata da margini più alti per singola transazione. La transizione richiede però sistemi dedicati di assistenza clienti e accordi specifici con grandi catene di alberghi d'eccellenza."
   ],
