   "titolo": "Cipro, il Partito Verde sollecita misure più severe contro l'abbandono di animali",
   "orig": "Greens demand action over abandoned animals",
   "lead": "Attraverso una nota ufficiale, i rappresentanti ecologisti hanno denunciato come tali incidenti riportino in primo piano l'emergenza dei cani randagi nel territorio cipriota. La formazione politica domanda sanzioni severe e piani di tutela per evitare che gli animali continuino a pagare le conseguenze dell'incuria umana sulle strade. Lo riferisce Cyprus Mail.",
   "more": [
    "Il fenomeno del randagismo nei Paesi dell'area mediterranea è spesso alimentato dall'assenza di microchippatura obbligatoria capillarmente controllata e dalle scarse campagne di sterilizzazione. L'abbandono crea rischi per la tutela del benessere animale e pericoli costanti per la sicurezza della circolazione stradale."
   ],
