   "sez": "musica",
   "titolo": "Bob Dylan rinnova il classico «Tangled Up in Blue» nei concerti europei con due strofe inedite",
   "orig": "Elogio della “nuova”, flebile ‘Tangled Up in Blue’",
   "lead": "Nei concerti del suo recente tour europeo, Bob Dylan sta eseguendo una versione modificata del capolavoro «Tangled Up in Blue», arricchita dall'inclusione di due strofe mai cantate prima d'ora. La variazione sul palco riapre la riflessione su un brano iconico che non ha mai smesso di evolversi fin dalla sua pubblicazione originale, mutando nei testi e negli arrangiamenti strumentali attraverso decenni di esibizioni dal vivo. L'adattamento senile proposto dal cantautore statunitense mette in risalto la sua costante ricerca di riscrittura dei classici del proprio repertorio anche a distanza di oltre cinquant'anni dal debutto. Lo riferisce Rolling Stone Italia.",
   "more": [
    "«Tangled Up in Blue» è la celebre traccia di apertura dell'album 'Blood on the Tracks', pubblicato da Bob Dylan nel 1975. Caratterizzata da una struttura narrativa fluida in cui mutano prospettive temporali e punti di vista, la canzone è stata costantemente modificata dall'autore nel corso delle sue esibizioni dal vivo."
   ],
